"use client";

import { useId, useState } from "react";

export function FloatingInputTailwind({ label = "Email address", helperText = "We'll only use this to send you receipts." }) {
  const id = useId();
  const [value, setValue] = useState("");
  return (
    <div className="w-full max-w-sm space-y-1.5">
      <div className="group relative flex h-13 items-center rounded-xl border border-zinc-800 bg-zinc-900 transition focus-within:border-indigo-500 focus-within:ring-4 focus-within:ring-indigo-500/25">
        <input id={id} value={value} onChange={(e) => setValue(e.target.value)} placeholder=" " aria-describedby={`${id}-help`} className="peer h-full w-full bg-transparent px-3.5 pt-4 text-[15px] text-zinc-100 outline-none" />
        <label htmlFor={id} className="pointer-events-none absolute left-3.5 top-[30%] origin-left -translate-y-1/2 scale-[0.78] text-zinc-400 transition-all duration-200 peer-placeholder-shown:top-1/2 peer-placeholder-shown:scale-100 peer-focus:top-[30%] peer-focus:scale-[0.78] peer-focus:text-indigo-400">{label}</label>
        {value && (
          <button type="button" aria-label={`Clear ${label}`} onClick={() => setValue("")} className="mr-2 grid size-6 shrink-0 place-items-center rounded-full text-zinc-500 hover:bg-zinc-800 hover:text-zinc-100">×</button>
        )}
      </div>
      <p id={`${id}-help`} className="px-1 text-[13px] text-zinc-400">{helperText}</p>
    </div>
  );
}
